1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
43	
44	const PROCESSING_FEE = 5;
45	
46	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
47	
48	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
49	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
50	
51	/** The closed set of insurable item types, each with its base premium in gold. */
52	const BASE_PREMIUMS = {
53	  sword: 100,
54	  amulet: 60,
55	  staff: 80,
56	  potion: 40,
57	  rune: 25,
58	  moonstone: 25,
59	} as const satisfies Record<string, number>;
60	
61	export type ItemType = keyof typeof BASE_PREMIUMS;
62	
63	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
64	
65	const BLOCK_SIZE = 3;
66	const BLOCK_BASE_PREMIUM = 60;
67	
68	/** Groups items by type; "alike" means same type, not same family. */
69	const groupByType = (items: Item[]): Item[][] => {
70	  const types = [...new Set(items.map((item) => item.type))];
71	  return types.map((type) => items.filter((item) => item.type === type));
72	};
73	
74	const COMPONENT_TYPES = new Set<string>(["rune", "moonstone"]);
75	
76	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
77	
78	/** Three alike components form a block, priced at a special base premium. */
79	const basePremiumOfGroup = (group: Item[]): number =>
80	  group.length === BLOCK_SIZE && group.every(isComponent)
81	    ? BLOCK_BASE_PREMIUM
82	    : sum(group.map(basePremiumOf));
83	
84	const totalBasePremium = (items: Item[]): number =>
85	  sum(groupByType(items).map(basePremiumOfGroup));
86	
87	const CURSE_SURCHARGE_RATE = 0.5;
88	
89	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
90	const HIGH_ENCHANTMENT_THRESHOLD = 5;
91	
92	const isCursed = (item: Item): boolean => item.cursed === true;
93	
94	const isHighlyEnchanted = (item: Item): boolean =>
95	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
96	
97	const itemSurchargeRate = (item: Item): number =>
98	  (isCursed(item) ? CURSE_SURCHARGE_RATE : 0) +
99	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
100	
101	/**
102	 * Item-specific surcharges apply to the affected item's own base premium,
103	 * unlike policy-wide modifiers which apply to the policy's total base premium.
104	 *
105	 * NOTE: this uses each item's ungrouped base premium, so a cursed component
106	 * inside a 3-alike block is surcharged against its own 25 G rather than its
107	 * share of the block's 60 G. No test covers that combination yet; the choice
108	 * is unverified, not deliberate.
109	 */
110	const totalItemSurcharges = (items: Item[]): number =>
111	  sum(items.map((item) => basePremiumOf(item) * itemSurchargeRate(item)));
112	
113	const LOYALTY_DISCOUNT_RATE = 0.2;
114	const LOYALTY_THRESHOLD_YEARS = 2;
115	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
116	
117	const isLoyal = (customer: Customer): boolean =>
118	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
119	
120	/**
121	 * Policy-wide modifiers apply to the policy's base premium, not to the item
122	 * surcharges. Returns a signed rate: the first-insurance surcharge less the
123	 * loyalty discount, so a loyal customer's rate can be negative.
124	 */
125	const policyModifierRate = (customer: Customer, isFollowUpContract: boolean): number =>
126	  FIRST_INSURANCE_SURCHARGE_RATE -
127	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
128	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
129	
130	const quotePremium = (
131	  items: Item[],
132	  customer: Customer,
133	  isFollowUpContract: boolean,
134	): number => {
135	  const basePremium = totalBasePremium(items);
136	  const premiumBeforeFee =
137	    basePremium +
138	    totalItemSurcharges(items) +
139	    basePremium * policyModifierRate(customer, isFollowUpContract);
140	  return roundPremium(premiumBeforeFee + PROCESSING_FEE);
141	};
142	
143	const INSURANCE_VALUES: Record<ItemType, number> = {
144	  sword: 1000,
145	  amulet: 600,
146	  staff: 800,
147	  potion: 400,
148	  rune: 250,
149	  moonstone: 250,
150	};
151	
152	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type as ItemType];
153	
154	const DEDUCTIBLE = 100;
155	const CAP_MULTIPLIER = 2;
156	
157	/** Rounds down in the MHPCO's favor. */
158	const roundPayout = (amount: number): number => Math.floor(Number(amount.toFixed(6)));
159	
160	interface Policy {
161	  items: Item[];
162	  remainingCap: number;
163	}
164	
165	const openPolicy = (items: Item[]): Policy => ({
166	  items,
167	  remainingCap: sum(items.map(insuranceValueOf)) * CAP_MULTIPLIER,
168	});
169	
170	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
171	const HALVED_REIMBURSEMENT_RATE = 0.5;
172	const FULL_REIMBURSEMENT_RATE = 1;
173	
174	/** Damage to a heavily enchanted item is only half reimbursed. */
175	const reimbursementRate = (item: Item): number =>
176	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD
177	    ? HALVED_REIMBURSEMENT_RATE
178	    : FULL_REIMBURSEMENT_RATE;
179	
180	/** The deductible is withheld once per damaged item, not once per incident. */
181	const reimbursementAfterDeductible = (damage: Damage, item: Item): number =>
182	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
183	
184	/** Draws down the policy's remaining cap as a side effect. */
185	const settleClaim = (policy: Policy, incident: Incident): Result => {
186	  const claimedBeforeCap = sum(
187	    incident.damages.map((damage) => {
188	      const item = policy.items.find((insured) => insured.type === damage.itemType);
189	      if (item === undefined) throw new Error(`Item not insured: ${damage.itemType}`);
190	      return reimbursementAfterDeductible(damage, item);
191	    }),
192	  );
193	  const payout = roundPayout(Math.min(claimedBeforeCap, policy.remainingCap));
194	  policy.remainingCap -= payout;
195	  return { payout, remainingCap: policy.remainingCap };
196	};
197	
198	export const runScenario = (scenario: Scenario): { results: Result[] } => {
199	  const policies = new Map<number, Policy>();
200	  let quotesSoFar = 0;
201	
202	  const results = scenario.steps.map((step, stepIndex) => {
203	    if (step.op === "quote") {
204	      const premium = quotePremium(step.items, scenario.customer, quotesSoFar > 0);
205	      quotesSoFar += 1;
206	      policies.set(stepIndex, openPolicy(step.items));
207	      return { premium };
208	    }
209	    const policy = policies.get(step.policy);
210	    if (policy === undefined) throw new Error(`No policy at step ${step.policy}`);
211	    return settleClaim(policy, step.incident);
212	  });
213	
214	  return { results };
215	};
